         &&& self.local_updates.dom().finite()
         &&& self.combiner.dom().finite()
     }



     #[invariant]
     pub fn inv_local_combiner_complete(&self) -> bool {
         forall |node_id: NodeId| 0 <= node_id < self.num_replicas <==>
