    match update {
        UpdateState::Applied { ret, idx } => {
            ret == DT::dispatch_mut_spec(compute_nrstate_at_version(self.log, idx), self.log[idx].op).1
        },
        UpdateState::Done { ret, idx } => {
            ret == DT::dispatch_mut_spec(compute_nrstate_at_version(self.log, idx), self.log[idx].op).1
        },
        _ => true,
    }
}


