    pub open spec fn wf_combiner_for_node_id(&self, node_id: NodeId) -> bool
        recommends self.wf_node_id(node_id)
    {
        match self.combiner[node_id] {
            CombinerState::Ready => {
                &&& LogRangeNoNodeId(self.log, self.local_versions[node_id], self.tail, node_id)
