        0 <= bound <= queued_ops.len(),
{
    forall|j|
        bound <= j < queued_ops.len() ==> {
            &&& localUpdates.contains_key(#[trigger] queued_ops[j])
            &&& localUpdates[queued_ops[j]].is_Placed()
