             );
         } else {
             LogRangeMatchesQueue_append_other(
                 queue,
                 log,
                 new_log,
                 queueIndex,
                 logIndexLower + 1,
                 logIndexUpper,
                 logLen,
                 node_id,
                 updates,
                 new_updates,
                 new_rid,
                 log_entry,
             );
         }
     }
